# -*- coding: utf-8 -*-
"""
从 R01（真实政府采购合同模板）派生 R02：把全部占位与空白填妥，**条款文字一字不动**。

目的：R01 因为是空白模板，在 intake 就被合规地拦下（TERMINATED_INTAKE_BLOCKED），
流水线根本没走到法域审计，`legal_citations_made: 0` —— 也就是说本次引入的
「开卷考」法条全文库一次都没被检索过。R02 存在的唯一理由就是让流水线跑完全程。

刻意保留的真实缺陷（这些是验收判据，不许在填空时顺手修掉）：
  - 引用已废止的《中华人民共和国合同法》（2021-01-01 被民法典取代）
  - 违约责任（五）(七)(八)：买方违约的"后果"是行政处分，卖方拿不到民事救济
  - 付款方式尾款「工程安装调试后」无时限、不挂钩验收

刻意植入的一处缺陷（用来验证 Agent 是否真去库里查条号，而不是凭记忆写）：
  - 争议解决勾选①仲裁，但仲裁机构写"买方所在地仲裁机构"——未选定具体机构。
    rules.yaml 声称依据是仲裁法第十六/十八条，而库里 2025 修订版那两条讲的是
    仲裁机构变更登记与组成人员，真正对应的是第二十九条。凭记忆写条号必错。
"""
import re, sys, hashlib

SRC = 'R01-govt-purchase-real.md'
DST = 'R02-govt-purchase-executed.md'

lines = open(SRC, encoding='utf-8').read().split('\n')
body = '\n'.join(lines[:120])   # 货物类模板段（intake 已确认 lines 1-120）

# (旧文本, 新文本, 期望命中次数)
SUBS = [
    ('项目名称（填写项目名称，分包项目如仪器设备类应填写到包别）',
     '项目名称：智慧教室多媒体设备采购项目（第1包：交互式一体机）', 1),
    ('任务书编号：XXXXXXXXXXX-1', '任务书编号：AHJZU-2026-HW-0417-1', 1),
    ('项目编号：XXXXXXXXXXXX', '项目编号：AHJZU-CG-2026-0417', 1),
    ('合同编号：XXXXXXXXXXXX', '合同编号：AHJZU-HT-2026-0417', 1),
    ('买  方：XXXXXXXXXXXX                  电话：XXX-XXXXXX',
     '买  方：安徽建筑大学                  电话：0551-63828001', 1),
    ('卖  方：XXXXXXXXXXXX                  电话： XXX-XXXXXX',
     '卖  方：合肥中鼎智能科技有限公司      电话：0551-65778820', 1),
    ('见证方：XXXXXXXXXXXX                  电话： XXX-XXXXXX',
     '见证方：安徽公信招标咨询有限公司      电话：0551-62826600', 1),
    ('买方通过招标代理机构名称组织的填写采购方式（包括公开招标、竞争性磋商、竞争性谈判、询价、单一来源等）方式采购活动，经填写评标委员会、磋商小组、谈判小组、询价小组等的评审，',
     '买方通过安徽公信招标咨询有限公司组织的公开招标方式采购活动，经评标委员会的评审，', 1),
    # 三、合同金额
    ('本合同的总金额为       元(人民币大写：        )。',
     '本合同的总金额为 1,286,000.00 元(人民币大写：壹佰贰拾捌万陆仟元整)。', 1),
    # 四、供货期限
    ('卖方应于合同签字生效后开始计算的    日内将货物送到买方指定的地点，由买方进行验收。',
     '卖方应于合同签字生效后开始计算的 45 日内将货物送到买方指定的地点，由买方进行验收。', 1),
    ('货物运输至买方指定地点到货物验收合格前，       负责对货物承担安保义务。',
     '货物运输至买方指定地点到货物验收合格前，卖方 负责对货物承担安保义务。', 1),
    # 七、售后服务（6 处空）
    ('卖方对合同货物的质量保修期为验收证书签署之日起  个月。',
     '卖方对合同货物的质量保修期为验收证书签署之日起 36 个月。', 1),
    ('服务的时间是：每周      天      小时（工作时间）。',
     '服务的时间是：每周 5 天 8 小时（工作时间）。', 1),
    ('或接到买方提出的技术服务要求后      小时内予以答复，如买方有要求或必要时，卖方应在接到买方通知后      小时内派员至买方免费维修和提供现场指导。',
     '或接到买方提出的技术服务要求后 2 小时内予以答复，如买方有要求或必要时，卖方应在接到买方通知后 24 小时内派员至买方免费维修和提供现场指导。', 1),
    ('（四）如卖方在接到买方维修通知后      小时仍不能修复有关货物',
     '（四）如卖方在接到买方维修通知后 48 小时仍不能修复有关货物', 1),
    ('或维修通知后      小时内没有响应', '或维修通知后 24 小时内没有响应', 1),
    ('卖方应在接到买方通知之后      小时内到达现场。',
     '卖方应在接到买方通知之后 48 小时内到达现场。', 1),
    # 八、履约保证金
    ('本项目履约保证金为           元(人民币大写：       )，收受人为           ，期限为验收合格后     。',
     '本项目履约保证金为 64,300.00 元(人民币大写：陆万肆仟叁佰元整)，收受人为 安徽建筑大学 ，期限为验收合格后 12 个月 。', 1),
    # 九、违约责任（只填比例，三项行政处罚条款原样保留）
    ('其标准为按每延期一周收取合同金额的   %', '其标准为按每延期一周收取合同金额的 0.5 %', 1),
    # 十、签约地点
    ('本合同在                                    签订。',
     '本合同在 安徽省合肥市蜀山区 签订。', 1),
    # 十二（四）争议解决 —— 勾选①，但仲裁机构未选定具体名称（刻意保留的缺陷）
    ('按以下第（ ）项方式处理：①根据《中华人民共和国仲裁法》的规定向\n           申请仲裁。',
     '按以下第（ ① ）项方式处理：①根据《中华人民共和国仲裁法》的规定向\n           买方所在地仲裁机构 申请仲裁。', 1),
    # 签署要素
    ('买    方：                           卖    方：             \n单位盖章：                           单位盖章：\n法定代表人或委托代理人：             法定代表人或委托代理人：\n日    期：                           日    期:',
     '买    方：安徽建筑大学               卖    方：合肥中鼎智能科技有限公司\n单位盖章：（已加盖单位公章）         单位盖章：（已加盖单位公章）\n法定代表人或委托代理人：王建国        法定代表人或委托代理人：陈立新\n日    期：2026年8月18日              日    期:2026年8月18日', 1),
    ('见证方:  \n单位盖章：\n法定代表人或委托代理人：\n日    期：',
     '见证方:  安徽公信招标咨询有限公司\n单位盖章：（已加盖单位公章）\n法定代表人或委托代理人：刘志远\n日    期：2026年8月18日', 1),
]

for old, new, want in SUBS:
    got = body.count(old)
    if got != want:
        sys.exit(f'✗ 替换未命中（{got}/{want}）：{old[:50]!r}')
    body = body.replace(old, new)

# 货物明细表：原文是散行表头 + 空表体，填入一条真实明细
TABLE_OLD = '产品名称\n规格型号\n单位\n数量\n单价\n小计\n生产厂商'
assert body.count(TABLE_OLD) == 1, '货物明细表头未命中'
body = body.replace(TABLE_OLD,
    '产品名称\t规格型号\t单位\t数量\t单价\t小计\t生产厂商\n'
    '交互式智能平板\tZD-IFP86A（86英寸）\t台\t40\t28,600.00\t1,144,000.00\t合肥中鼎智能科技有限公司\n'
    '智能中控主机\tZD-CTRL200\t套\t40\t3,550.00\t142,000.00\t合肥中鼎智能科技有限公司')
body = body.replace('合计\n\n合同总金额（大写）：',
                    '合计\t\t\t\t\t1,286,000.00\t\n\n合同总金额（大写）：壹佰贰拾捌万陆仟元整')

# 残留占位符自检 —— 填空没填干净的话下游还是会在 intake 被拦，白跑一趟
leftover = re.findall(r'X{3,}', body)
if leftover:
    sys.exit(f'✗ 仍有 {len(leftover)} 处 XXXX 占位未填')

# 必须原样保留的三处（验收判据，误改即失去意义）
MUST_KEEP = [
    '《中华人民共和国合同法》',                       # repealed-law-citation
    '（五）买方未能按时组织验收，由财政部门责令限期改正，给予警告',  # 行政处罚当救济
    '工程安装调试后,支付剩余货款',                     # 尾款无时限
]
for k in MUST_KEEP:
    if k not in body:
        sys.exit(f'✗ 应保留的原文被改掉了：{k}')

# 页码标记（intake 的 INV-006 页码连续性要求可核验分页）
paged = body.rstrip('\n') + '\n\n—— 第 1 页，共 3 页 ——\n'

open(DST, 'w', encoding='utf-8').write(paged)
digest = hashlib.sha256(paged.encode('utf-8')).hexdigest()
print(f'✓ 已生成 {DST}')
print(f'  字节 {len(paged.encode("utf-8"))}  行 {paged.count(chr(10))+1}')
print(f'  sha256 {digest}')
print(f'  保留《合同法》引用：{body.count("《中华人民共和国合同法》")} 处')
print(f'  提及民法典：{body.count("民法典")} 处')
